import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry unit', () => {
  it('caches compiled validators for function-valued tool definitions by schema reference ([validated by: A function-valued ToolDefinitionSource resolves its definition on each execute call and validates against the inputSchema returned for that call, caching compiled validators by schema object reference (WeakMap) so distinct returned schemas each enforce their own rules.](../../specs/hal-engine-tool-input-validation/spec.md))', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {location: {type: 'string'}}};
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');

    registry.register(
      () => ({
        name: 'get_weather',
        description: 'test',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    // First execution compiles and caches
    await registry.execute('get_weather', {location: 'Paris'});
    const firstCallCount = compileSpy.mock.calls.length;
    expect(firstCallCount).toBeGreaterThan(0);

    // Second execution should use cache
    await registry.execute('get_weather', {location: 'London'});
    expect(compileSpy.mock.calls.length).toBe(firstCallCount);

    compileSpy.mockRestore();
  });

  it('provides prompt instructions from all registered tools ([validated by: ToolRegistry.getPromptInstructions returns a list of formatted instructions from all registered tools that declare promptInstructions.](../../specs/hal-engine-tool-input-validation/spec.md))', () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'tool1',
        description: 'd1',
        inputSchema: {},
        promptInstructions: 'Instruction 1',
      },
      async () => ''
    );
    registry.register(
      {
        name: 'tool2',
        description: 'd2',
        inputSchema: {},
        promptInstructions: 'Instruction 2',
      },
      async () => ''
    );

    expect(registry.getPromptInstructions()).toEqual(['tool1: Instruction 1', 'tool2: Instruction 2']);
  });

  it('provides example prompts from all registered tools ([validated by: ToolRegistry.getExamplePrompts returns a flattened list of all example prompts from all registered tools.](../../specs/hal-engine-tool-input-validation/spec.md))', () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'tool1',
        description: 'd1',
        inputSchema: {},
        examplePrompts: ['p1', 'p2'],
      },
      async () => ''
    );
    registry.register(
      {
        name: 'tool2',
        description: 'd2',
        inputSchema: {},
        examplePrompts: ['p3'],
      },
      async () => ''
    );

    expect(registry.getExamplePrompts()).toEqual(['p1', 'p2', 'p3']);
  });

  it('passes through extra properties unchanged ([validated by: When input satisfies required, declared property types and enum, ToolRegistry.execute invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting additionalProperties: false, coercing types or applying defaults.](../../specs/hal-engine-tool-input-validation/spec.md))', async () => {
    const registry = new ToolRegistry();
    let capturedInput: any;
    registry.register(
      {
        name: 'test',
        description: 'd',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    const input = {a: 'val', extra: 'prop'};
    await registry.execute('test', input);

    expect(capturedInput).toEqual(input);
  });

  it('throws for unregistered tool names ([validated by: When ToolRegistry.execute is called with a tool name that has not been registered, it throws Unknown tool: <name> because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.](../../specs/hal-engine-tool-input-validation/spec.md))', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('compiles static schema once at register time ([validated by: A static tool\'s inputSchema is compiled at register time and reused on every execute call without re-reading or re-compiling definition.inputSchema.](../../specs/hal-engine-tool-input-validation/spec.md))', async () => {
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'static_tool',
        description: 'd',
        inputSchema: {type: 'object'},
      },
      async () => 'ok'
    );

    expect(compileSpy).toHaveBeenCalledTimes(1);
    const countAfterRegister = compileSpy.mock.calls.length;

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {});
    }

    expect(compileSpy.mock.calls.length).toBe(countAfterRegister);
    compileSpy.mockRestore();
  });

  it('redacts values from logs and results on validation failure ([validated by: When input supplies a property whose value does not match its declared JSON Schema type, ToolRegistry.execute returns a ToolResponse naming the failing field path and expected type without invoking the executor, and neither result nor the emitted log record contains the offending property value.](../../specs/hal-engine-tool-input-validation/spec.md))', async () => {
    const recordedLogs: string[] = [];
    const logger: Logger = {
      debug: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
      info: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
      warn: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
      error: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    const SECRET = 'SECRET_VALUE_123';
    registry.register(
      {
        name: 'tool',
        description: 'd',
        inputSchema: {type: 'object', properties: {val: {type: 'string'}}},
      },
      async () => 'ok'
    );

    const response = await registry.execute('tool', {val: 123} as any); // Should be string
    // Inject the secret as an extra property that fails something if we used additionalProperties: false, 
    // but here we just test that the VALUE of the failing property isn't leaked.
    const response2 = await registry.execute('tool', {val: 123, secret: SECRET} as any);

    expect(response2.result).not.toContain(SECRET);
    expect(recordedLogs.some(l => l.includes(SECRET))).toBe(false);

    setLogger(undefined);
  });

  it('validates against the current schema for function-valued definitions ([validated by: A function-valued ToolDefinitionSource resolves its definition on each execute call and validates against the inputSchema returned for that call, caching compiled validators by schema object reference (WeakMap) so distinct returned schemas each enforce their own rules.](../../specs/hal-engine-tool-input-validation/spec.md))', async () => {
    const registry = new ToolRegistry();
    let schema: any = {type: 'object', properties: {a: {type: 'string'}}};

    registry.register(
      () => ({
        name: 'dynamic',
        description: 'd',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    // First call with schema requiring 'a' as string
    const res1 = await registry.execute('dynamic', {a: 1});
    expect(res1.result).toContain('Validation failed');

    // Change schema to require 'a' as number
    schema = {type: 'object', properties: {a: {type: 'number'}}};
    const res2 = await registry.execute('dynamic', {a: 1});
    expect(res2.result).toBe('ok');

    const res3 = await registry.execute('dynamic', {a: 'string'});
    expect(res3.result).toContain('Validation failed');
  });
});

